const job = $('Get Generation Job').first().json;
const snap = job.input_snapshot || {};
const user = snap.user || {};
const pet = snap.pet || {};
const trip = snap.trip || {};
const jobId = job.id || $('Webhook').first().json.body.job_id;

const style = 'Consistent warm, premium illustrated travel-journal style, cozy hand-painted look with soft warm lighting, cream and orange tones.';

const ownerPhoto = user.photo_path || '';
const petPhoto = pet.photo_path || '';
let photoStrategy = 'generic_both';
if (ownerPhoto && petPhoto) photoStrategy = 'both_refs';
else if (petPhoto) photoStrategy = 'pet_ref_generic_owner';
else if (ownerPhoto) photoStrategy = 'owner_ref_generic_pet';

const petDesc = [pet.size_category, pet.breed, pet.pet_type].filter(Boolean).join(' ') || 'pet';

const mode = String(trip.travel_mode || '').toLowerCase();
let travelScene;
if (mode === 'air') travelScene = 'the owner and their ' + petDesc + ' safely seated inside an airplane, calmly looking out through the window at the clouds';
else if (mode === 'rail') travelScene = 'the owner and their ' + petDesc + ' sitting beside a First AC train window, the pet appearing happy and curious';
else if (mode === 'road') travelScene = 'the owner and their ' + petDesc + ' inside a car, the pet safely restrained with a harness, calmly enjoying fresh air from a partially open window, no unsafe behavior';
else travelScene = 'the owner and their ' + petDesc + ' happily beginning their journey to ' + (trip.destination || 'the destination');

function refNote() {
  if (photoStrategy === 'both_refs') return ' Depict the real owner and the real pet based on provided references.';
  if (photoStrategy === 'pet_ref_generic_owner') return ' Depict the real pet; render a generic tasteful owner.';
  if (photoStrategy === 'owner_ref_generic_pet') return ' Depict the real owner; render a generic ' + petDesc + '.';
  return ' Render a generic ' + petDesc + ' and a generic owner.';
}

const image1Prompt = style + ' Scene: ' + travelScene + '. Destination context: ' + (trip.destination || '') + '.' + refNote();

const notes = String(snap.notes || '').toLowerCase();
let prefScene = '';
let prefLabel = '';
if (notes.indexOf('walk') !== -1) { prefScene = 'the owner and their ' + petDesc + ' enjoying a long scenic walk together'; prefLabel = 'long walks'; }
else if (notes.indexOf('sunset') !== -1) { prefScene = 'the owner and their ' + petDesc + ' watching a beautiful golden sunset together'; prefLabel = 'sunsets'; }
else if (notes.indexOf('beach') !== -1) { prefScene = 'the owner and their ' + petDesc + ' relaxing on a warm sandy beach'; prefLabel = 'beaches'; }
else if (notes.indexOf('trail') !== -1 || notes.indexOf('nature') !== -1 || notes.indexOf('hike') !== -1) { prefScene = 'the owner and their ' + petDesc + ' exploring a lush green nature trail'; prefLabel = 'nature trails'; }
else if (notes.indexOf('relax') !== -1) { prefScene = 'the owner and their ' + petDesc + ' relaxing peacefully at the destination'; prefLabel = 'relaxing at the destination'; }

let scene2 = 'preference';
if (!prefScene) { prefScene = 'the owner and their ' + petDesc + ' happily arriving at ' + (trip.destination || 'the destination'); prefLabel = 'destination arrival'; scene2 = 'destination'; }

const image2Prompt = style + ' Scene: ' + prefScene + '. Location around ' + (trip.destination || '') + '.' + refNote();

const base = 'generated/' + jobId + '/';
function cap(s){ return s ? s.charAt(0).toUpperCase() + s.slice(1) : s; }

return [
  { json: { index: 1, scene: 'travel', scene_label: (trip.travel_mode || 'travel'), caption: 'Your journey: ' + (trip.origin || '') + ' to ' + (trip.destination || '') + ' by ' + (trip.travel_mode || 'travel'), prompt: image1Prompt, storage_path: base + 'image-travel.png', photo_strategy: photoStrategy } },
  { json: { index: 2, scene: scene2, scene_label: prefLabel, caption: cap(prefLabel), prompt: image2Prompt, storage_path: base + 'image-preference.png', photo_strategy: photoStrategy } }
];

const items = $input.all();
const images = items
  .filter(it => it.json && it.json.image_data_uri)
  .map(it => ({
    scene: it.json.scene,
    scene_label: it.json.scene_label,
    caption: it.json.caption,
    storage_path: it.json.storage_path,
    image_data_uri: it.json.image_data_uri,
  }));
return [{ json: { images } }];

const job = $('Get Generation Job').first().json;
const snap = job.input_snapshot || {};
const user = snap.user || {};
const pet = snap.pet || {};
const trip = snap.trip || {};
const itinerary = snap.itinerary || {};
const days = Array.isArray(itinerary.days) ? itinerary.days : [];
const images = ($('Aggregate Images').first().json.images) || [];

function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function imgFor(scene){
  const found = images.find(i => i.scene === scene);
  if (!found || !found.image_data_uri) return '';
  return '<figure class="photo"><img src="' + found.image_data_uri + '" alt="' + esc(found.caption) + '"/><figcaption>' + esc(found.caption) + '</figcaption></figure>';
}
const prefImage = images.find(i => i.scene === 'preference' || i.scene === 'destination');
const prefImageHtml = (prefImage && prefImage.image_data_uri) ? '<figure class="photo"><img src="' + prefImage.image_data_uri + '" alt="' + esc(prefImage.caption) + '"/><figcaption>' + esc(prefImage.caption) + '</figcaption></figure>' : '';

let daysHtml = '';
if (days.length === 0) {
  daysHtml = '<p class="muted">A detailed day-by-day plan will appear here.</p>';
} else {
  for (let d = 0; d < days.length; d++) {
    const day = days[d] || {};
    const acts = Array.isArray(day.items) ? day.items : [];
    let actsHtml = '';
    for (let a = 0; a < acts.length; a++) { actsHtml += '<li>' + esc(acts[a]) + '</li>'; }
    daysHtml += '<div class="day"><h3>Day ' + esc(day.day || (d + 1)) + ': ' + esc(day.title || '') + '</h3><ul>' + actsHtml + '</ul></div>';
    if (d === 0 && prefImageHtml) { daysHtml += prefImageHtml; }
  }
}

const parts = [];
parts.push('<!DOCTYPE html><html><head><meta charset="utf-8"/>');
parts.push('<style>');
parts.push('body{font-family:Georgia,"Times New Roman",serif;color:#4a3527;background:#fbf3e7;margin:0;padding:32px;}');
parts.push('h1{color:#c8641a;font-size:34px;margin:0 0 4px;}');
parts.push('h2{color:#8a5a2b;border-bottom:2px solid #e6c9a3;padding-bottom:6px;margin-top:28px;}');
parts.push('h3{color:#a85e1c;margin-bottom:4px;}');
parts.push('.tagline{color:#8a5a2b;font-style:italic;margin-bottom:18px;}');
parts.push('.card{background:#fff8ef;border:1px solid #e6c9a3;border-radius:10px;padding:16px 20px;margin:12px 0;}');
parts.push('.grid{display:flex;gap:16px;flex-wrap:wrap;}');
parts.push('.grid .card{flex:1;min-width:220px;}');
parts.push('.photo{margin:16px 0;text-align:center;}');
parts.push('.photo img{max-width:100%;border-radius:10px;border:3px solid #e6c9a3;}');
parts.push('figcaption{color:#8a5a2b;font-style:italic;font-size:13px;margin-top:6px;}');
parts.push('.muted{color:#9b8b78;}');
parts.push('.notice{background:#fdeeda;border-left:5px solid #c8641a;padding:12px 16px;border-radius:6px;margin-top:20px;font-size:13px;}');
parts.push('ul{margin:6px 0 0 18px;}');
parts.push('</style></head><body>');

parts.push('<h1>Tail &amp; Compass</h1>');
parts.push('<div class="tagline">Your personalized pet-friendly travel itinerary</div>');

parts.push(imgFor('travel'));

parts.push('<h2>Trip Summary</h2>');
parts.push('<div class="card"><strong>' + esc(trip.origin || '') + '</strong> &rarr; <strong>' + esc(trip.destination || '') + '</strong><br/>');
parts.push('Dates: ' + esc(trip.start_date || '') + ' to ' + esc(trip.end_date || '') + '<br/>');
parts.push('Purpose: ' + esc(trip.purpose || '') + '</div>');

parts.push('<div class="grid">');
parts.push('<div class="card"><h3>Traveler</h3>' + esc(user.name || 'Guest') + '</div>');
parts.push('<div class="card"><h3>Pet</h3>' + esc(pet.name || '') + ' &middot; ' + esc([pet.size_category, pet.breed, pet.pet_type].filter(Boolean).join(' ')) + '<br/>Care profile: ' + esc(pet.care_profile || 'standard') + '</div>');
parts.push('</div>');

parts.push('<h2>Travel Mode &amp; Stay</h2>');
parts.push('<div class="card">Travel mode: <strong>' + esc(trip.travel_mode || '') + '</strong><br/>Selected stay: <strong>' + esc(trip.stay_name || trip.stay_option_id || 'Selected pet-friendly stay') + '</strong></div>');

parts.push('<h2>Day-by-Day Itinerary</h2>');
parts.push(daysHtml);

parts.push('<h2>Your Notes</h2>');
parts.push('<div class="card">' + esc(snap.notes || 'No additional notes provided.') + '</div>');

parts.push('<div class="notice"><strong>Policy verification reminder:</strong> Pet travel and stay policies vary by operator and can change. Please reconfirm carrier, accommodation and destination pet policies before you travel.</div>');
parts.push('<div class="notice"><strong>Disclaimer:</strong> Availability and operator policies must be reconfirmed before booking. This itinerary is a personalized suggestion, not a confirmed reservation.</div>');

parts.push('</body></html>');

return [{ json: { html: parts.join('') } }];

const plan = $('Prepare Image Plan').item.json;
const mode = String($('Get Generation Job').first().json.input_snapshot?.trip?.travel_mode || 'travel');
const pet = String($('Get Generation Job').first().json.input_snapshot?.pet?.pet_type || 'pet');
const title = encodeURIComponent('Tail & Compass');
const subtitle = encodeURIComponent('A happy ' + pet + ' ' + mode + ' journey');
const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="700"><rect width="1200" height="700" fill="#fff4e6"/><circle cx="600" cy="275" r="145" fill="#ed7b19"/><text x="600" y="305" text-anchor="middle" font-size="72" fill="#4a2412">' + pet.charAt(0).toUpperCase() + '</text><text x="600" y="505" text-anchor="middle" font-family="Georgia" font-size="52" fill="#4a2412">' + decodeURIComponent(title) + '</text><text x="600" y="570" text-anchor="middle" font-family="Arial" font-size="28" fill="#8a5a2b">' + decodeURIComponent(subtitle) + '</text></svg>';
return [{ json: { scene: plan.scene, scene_label: plan.scene_label, caption: plan.caption, storage_path: null, image_data_uri: 'data:image/svg+xml;base64,' + Buffer.from(svg).toString('base64'), used_fallback: true } }];
